import React, { forwardRef, useCallback, useImperativeHandle, useRef } from "react";
import { WebView, type WebViewMessageEvent } from "react-native-webview";
import { useWallet } from "../wallet/WalletProvider";
import { useApp } from "../store";
import { b64ToBytes, bytesToB64 } from "../lib/bytes";
import type { BridgeInbound, BridgeMethod, SignResponseMsg, SignTxResponseMsg } from "../lib/rpc";
// Generated by `bun run build:bridge` (the bridge HTML as a string).
import BRIDGE_HTML from "../../bridge/dist/bridge-html";

export interface SdkBridgeHandle {
  call: <T = unknown>(method: BridgeMethod, args?: unknown[]) => Promise<T>;
}

type Pending = { resolve: (v: unknown) => void; reject: (e: Error) => void };

/**
 * Hidden WebView that hosts the privacy-cash SDK (WASM + Web Crypto). The RN
 * layer drives it via postMessage RPC; signMessage round-trips to the native
 * wallet. See bridge/README.md.
 */
export const SdkWebView = forwardRef<SdkBridgeHandle>(function SdkWebView(_props, ref) {
  const webRef = useRef<WebView>(null);
  const wallet = useWallet();
  const backendUrl = useApp((s) => s.backendUrl);
  const circuitBase = useApp((s) => s.circuitBase);
  const setBridgeStatus = useApp((s) => s.setBridgeStatus);

  const pending = useRef<Map<number, Pending>>(new Map());
  const idc = useRef(0);

  const inject = useCallback((obj: object) => {
    webRef.current?.injectJavaScript(
      "window.__pcash&&window.__pcash.inject(" + JSON.stringify(obj) + ");true;",
    );
  }, []);

  const injectSignResponse = useCallback((msg: SignResponseMsg | SignTxResponseMsg) => {
    webRef.current?.injectJavaScript(
      "window.__pcash&&window.__pcash.inject(" + JSON.stringify(msg) + ");true;",
    );
  }, []);

  const call = useCallback(
    <T,>(method: BridgeMethod, args: unknown[] = []): Promise<T> => {
      return new Promise<T>((resolve, reject) => {
        const id = ++idc.current;
        pending.current.set(id, {
          resolve: resolve as (v: unknown) => void,
          reject,
        });
        inject({ id, type: "call", method, args });
      });
    },
    [inject],
  );

  useImperativeHandle(ref, () => ({ call }), [call]);

  const onMessage = useCallback(
    async (e: WebViewMessageEvent) => {
      let msg: BridgeInbound;
      try {
        msg = JSON.parse(e.nativeEvent.data) as BridgeInbound;
      } catch {
        return;
      }
      switch (msg.type) {
        case "ready":
          setBridgeStatus({ ready: true, webcrypto: msg.webcrypto, hasSdk: msg.hasSdk });
          return;
        case "signRequest": {
          try {
            const bytes = b64ToBytes(msg.messageB64);
            const sig = await wallet.signMessage(bytes);
            injectSignResponse({
              signId: msg.signId,
              type: "signResponse",
              signatureB64: bytesToB64(sig),
            });
          } catch (err: any) {
            injectSignResponse({
              signId: msg.signId,
              type: "signResponse",
              error: err?.message ?? "signMessage failed",
            });
          }
          return;
        }
        case "signTxRequest": {
          // The SDK built a deposit tx in the WebView; route it to the native
          // wallet for signing (deposits need the user's signature), then return
          // the signed bytes. sendPrivateSOL / sendPrivateSPL depend on this.
          try {
            const signedB64 = await wallet.signTransaction(msg.txB64);
            injectSignResponse({
              signId: msg.signId,
              type: "signTxResponse",
              signedTxB64: signedB64,
            });
          } catch (err: any) {
            injectSignResponse({
              signId: msg.signId,
              type: "signTxResponse",
              error: err?.message ?? "signTransaction failed",
            });
          }
          return;
        }
        case "result": {
          const p = pending.current.get(msg.id);
          if (!p) return;
          pending.current.delete(msg.id);
          if (msg.ok) p.resolve(msg.data);
          else p.reject(new Error(msg.error));
          return;
        }
      }
    },
    [wallet, setBridgeStatus, injectSignResponse],
  );

  // Config injected before the page scripts run. Remounts when the wallet OR
  // the backend/circuit settings change (key), so a newly-connected wallet
  // re-initializes the SDK client and a Settings save takes effect without
  // reconnecting the wallet (otherwise the bridge keeps the old URL forever).
  const configJs =
    "window.__PCASH_CONFIG__=" +
    JSON.stringify({
      walletPubkey: wallet.address ?? "",
      backendUrl,
      circuitBase,
    }) +
    ";true;";

  return (
    <WebView
      key={(wallet.address ?? "no-wallet") + "|" + backendUrl + "|" + circuitBase}
      ref={webRef}
      // baseUrl MUST be an https origin. With just {html} the page loads as
      // about:blank -> NOT a secure context -> window.crypto.subtle is undefined
      // -> the SDK's AES-256-GCM note encrypt/decrypt throws -> balance stays 0.
      // An https baseUrl makes loadDataWithBaseURL treat the document as a secure
      // context, so crypto.subtle is available. (All SDK fetches are absolute or
      // rewritten by the bridge-host fetch override, so the baseUrl host is never
      // actually contacted.)
      source={{ html: BRIDGE_HTML, baseUrl: "https://localhost/" }}
      originWhitelist={["*"]}
      injectedJavaScriptBeforeContentLoaded={configJs}
      onMessage={onMessage}
      javaScriptEnabled
      domStorageEnabled
      // Render off-screen but at a real size: Android suspends JS in 1x1 / fully
      // transparent WebViews, which hangs every RPC call (balance never loads).
      // A normal-size view parked off-screen keeps the JS engine alive.
      style={{
        position: "absolute",
        left: -9999,
        top: 0,
        width: 320,
        height: 480,
        opacity: 0.01,
        backgroundColor: "#0C0E12",
      }}
      onLoad={(e) => {
        // re-inject config defensively (some platforms drop before-content injection)
        webRef.current?.injectJavaScript(configJs);
      }}
    />
  );
});
